"""
Centralized SVG icons for MarkItDown Desktop.
Provides crisp, native-feeling vector icons using QSvgRenderer.
"""
from PySide6.QtGui import QIcon, QPixmap, QPainter, QColor
from PySide6.QtCore import QByteArray
try:
    from PySide6.QtSvg import QSvgRenderer
    HAS_SVG = True
except ImportError:
    HAS_SVG = False

# Clean, Feather-style paths for a native macOS feel
